<?php
declare(strict_types=1);
require __DIR__.'/lib.php';require_once __DIR__.'/lib/communication.php';require_once __DIR__.'/lib/user_preferences.php';
header('Cache-Control: no-store, private');$account=lab_auth_current_account();$admin=scom_admin($account);$uid=(string)$account['id'];$db=lab_auth_pdo();scom_schema($db);
$embed=!empty($_GET['embed']);$tab=$admin&&($_GET['tab']??'')==='notices'?'notices':'suggestions';$theme=lab_user_theme($uid);$csrf=lab_auth_csrf_token();$selected=null;$messages=[];$error='';
$states=['new'=>'Nueva','review'=>'En revisión','answered'=>'Respondida','closed'=>'Cerrada'];$users=$admin?scom_query($db,'SELECT id,username FROM users WHERE is_active=1 ORDER BY username'):[];
$id=(string)($_GET['thread']??'');if($id!==''){try{$selected=scom_thread($db,$account,$id);$before=max(0,(int)($_GET['before']??0));$messages=scom_query($db,'SELECT m.id,m.author,m.body,m.created_at,u.username,u.role FROM sf_com_messages m LEFT JOIN users u ON u.id=m.author WHERE m.thread_id=?'.($before?' AND m.id<?':'').' ORDER BY m.id DESC LIMIT 100',$before?[$id,$before]:[$id]);$messages=array_reverse($messages);}catch(DomainException $e){http_response_code(403);$error=$e->getMessage();}}
$offset=max(0,min(100000,(int)($_GET['offset']??0)));$where=[];$args=[$uid];
if(!$admin){$where[]='t.user_id=?';$args[]=$uid;}
$filter=(string)($_GET['status']??'');if(isset($states[$filter])){$where[]='t.status=?';$args[]=$filter;}
$owner=(string)($_GET['owner']??'');if($admin&&$owner!==''){$where[]='t.user_id=?';$args[]=$owner;}
$threads=scom_query($db,'SELECT t.*,u.username,COALESCE(r.last_id,0) read_id,(SELECT MAX(m.id) FROM sf_com_messages m WHERE m.thread_id=t.id AND m.author<>r.user_id) other_id FROM sf_com_threads t JOIN users u ON u.id=t.user_id LEFT JOIN sf_com_reads r ON r.thread_id=t.id AND r.user_id=?'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY t.updated_at DESC,t.id LIMIT 51 OFFSET '.$offset,$args);
// A missing read row also means unread; compare using the current account explicitly.
foreach($threads as &$t){$q=$db->prepare('SELECT MAX(id) FROM sf_com_messages WHERE thread_id=? AND author<>?');$q->execute([$t['id'],$uid]);$t['unread']=(int)$q->fetchColumn()>(int)$t['read_id'];}unset($t);
$notices=$admin&&$tab==='notices'?scom_query($db,'SELECT n.*,(SELECT COUNT(*) FROM sf_com_recipients r WHERE r.notice_id=n.id) total,(SELECT COUNT(*) FROM sf_com_recipients r WHERE r.notice_id=n.id AND r.confirmed_at IS NOT NULL) confirmed FROM sf_com_notices n ORDER BY n.created_at DESC,n.id LIMIT 51 OFFSET '.$offset):[];
$notice=null;$recipients=[];if($admin&&$tab==='notices'&&!empty($_GET['notice'])){$notice=scom_query($db,'SELECT * FROM sf_com_notices WHERE id=?',[(string)$_GET['notice']])[0]??null;if($notice)$recipients=scom_query($db,'SELECT u.username,r.confirmed_at FROM sf_com_recipients r JOIN users u ON u.id=r.user_id WHERE r.notice_id=? ORDER BY u.username',[$notice['id']]);}
$pref=scom_query($db,'SELECT notify FROM sf_com_preferences WHERE user_id=?',[$uid]);
function scom_date(int $stamp):string{return (new DateTimeImmutable('@'.$stamp))->setTimezone(new DateTimeZone('America/Mexico_City'))->format('d/m/Y H:i');}
function scom_hidden(string $action,string $csrf):void { ?><input type="hidden" name="action" value="<?=lab_h($action)?>"><input type="hidden" name="csrf_token" value="<?=lab_h($csrf)?>"><input type="hidden" name="request_key" value="<?=bin2hex(random_bytes(16))?>"><?php }
$base='communication.php?'.($embed?'embed=1&':'');
?><!doctype html><html lang="es" data-theme="<?=lab_h($theme)?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="sf-csrf" content="<?=lab_h($csrf)?>"><title><?=$admin?'Comunicación':'Sugerencias'?> · Sparrow-Fy</title><link rel="stylesheet" href="assets/lab.css?v=theme-sweep1"><link rel="stylesheet" href="assets/communication.css?v=1"><link rel="stylesheet" href="assets/save-feedback.css?v=2"><script src="assets/save-feedback.js?v=2"></script><script defer src=assets/sf-language.js></script></head><body>
<?php if(!$embed):?><header class="lab-header"><h1><?=$admin?'Comunicación':'Sugerencias'?></h1><a class="btn" href="<?=$admin?'config.php':'index.php'?>">Volver</a></header><?php endif;?>
<main class="lab-main sf-com-page"><h1><?=$admin?'Comunicación':'Sugerencias'?></h1><?php if($admin):?><nav class="sf-com-tabs" aria-label="Comunicación"><a class="btn <?=$tab==='notices'?'primary':''?>" href="<?=$base?>tab=notices">Avisos a usuarios</a><a class="btn <?=$tab==='suggestions'?'primary':''?>" href="<?=$base?>tab=suggestions">Sugerencias</a></nav><?php endif;?>
<?php if($error):?><p role="alert"><?=lab_h($error)?></p><?php endif;?>
<?php if($tab==='notices'):?>
<section class="card"><h2>Nuevo aviso</h2><p>Se mostrará al entrar o regresar a Sparrow-Fy. Solo dejará de aparecer cuando cada destinatario pulse «Leído, cerrar».</p><form data-com-form data-com-preview><?php scom_hidden('publish',$csrf);?><label>Título<input name="title" required maxlength="140"></label><label>Mensaje<textarea name="body" required maxlength="6000" rows="6"></textarea></label><label>Destinatarios<select name="audience" data-com-audience><option value="all">Todos los usuarios activos</option><option value="managers">Gestores y administradores</option><option value="selected">Usuarios específicos</option></select></label><fieldset data-com-recipients hidden><legend>Selecciona usuarios</legend><div class="sf-com-users"><?php foreach($users as $u):?><label><input type="checkbox" name="recipients[]" value="<?=lab_h((string)$u['id'])?>"> <?=lab_h($u['username'])?></label><?php endforeach;?></div></fieldset><button class="btn primary" type="submit">Revisar aviso y destinatarios</button><p data-com-feedback role="status"></p></form></section>
<section class="card"><h2>Avisos enviados</h2><div class="sf-com-table"><table><thead><tr><th>Aviso</th><th>Fecha</th><th>Confirmados</th><th>Estado</th></tr></thead><tbody><?php foreach(array_slice($notices,0,50) as $n):?><tr><td><a href="<?=$base?>tab=notices&notice=<?=lab_h($n['id'])?>"><?=lab_h($n['title'])?></a></td><td><?=scom_date($n['created_at'])?></td><td><?=$n['confirmed']?> / <?=$n['total']?></td><td><?=$n['cancelled_at']?'Cancelado':'Publicado'?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$notices):?><p>No has publicado avisos.</p><?php endif;?><?php if(count($notices)>50):?><a class="btn" href="<?=$base?>tab=notices&offset=<?=$offset+50?>">Siguientes</a><?php endif;?></section>
<?php if($notice):?><section class="card"><h2><?=lab_h($notice['title'])?></h2><p class="sf-com-text"><?=lab_h($notice['body'])?></p><h3>Entrega por destinatario</h3><ul><?php foreach($recipients as $r):?><li><?=lab_h($r['username'])?> — <?=$r['confirmed_at']?'Confirmado · '.scom_date($r['confirmed_at']):($notice['cancelled_at']?'Cancelado sin confirmar':'Pendiente')?></li><?php endforeach;?></ul><?php if(!$notice['cancelled_at']):?><form data-com-form><?php scom_hidden('cancel',$csrf);?><input type="hidden" name="id" value="<?=lab_h($notice['id'])?>"><button class="btn" type="submit">Cancelar entregas pendientes</button><p data-com-feedback role="status"></p></form><?php endif;?></section><?php endif;?>
<?php else:?>
<?php if($admin):?><section class="card"><h2>Preferencias de notificación</h2><form data-com-form data-com-stay><?php scom_hidden('preference',$csrf);?><label title="Activa avisos dentro de Sparrow-Fy para tu cuenta. No envía correo ni notificaciones push."><input type="checkbox" data-com-notify <?=!empty($pref[0]['notify'])?'checked':''?>> Notificarme cuando lleguen nuevas sugerencias o respuestas</label><input type="hidden" name="notify" value="<?=!empty($pref[0]['notify'])?'1':'0'?>"><button class="btn" type="submit">Guardar preferencia</button><p data-com-feedback role="status"></p></form></section><?php endif;?>
<section class="card"><h2>Enviar sugerencia</h2><p>La conversación es privada entre tu cuenta y los administradores.</p><form data-com-form><?php scom_hidden('create',$csrf);?><label>Asunto<input name="subject" required maxlength="140"></label><label>Mensaje<textarea name="body" required maxlength="6000" rows="5"></textarea></label><button class="btn primary" type="submit">Enviar sugerencia</button><p data-com-feedback role="status"></p></form></section>
<section class="card"><h2><?=$admin?'Sugerencias de usuarios':'Mis sugerencias'?></h2><form method="get" class="sf-com-filters"><?php if($embed):?><input type="hidden" name="embed" value="1"><?php endif;?><label>Estado<select name="status"><option value="">Todos</option><?php foreach($states as $v=>$label):?><option value="<?=$v?>" <?=$filter===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><?php if($admin):?><label>Usuario<select name="owner"><option value="">Todos</option><?php foreach($users as $u):?><option value="<?=lab_h((string)$u['id'])?>" <?=$owner===(string)$u['id']?'selected':''?>><?=lab_h($u['username'])?></option><?php endforeach;?></select></label><?php endif;?><button class="btn" type="submit">Filtrar</button></form><div class="sf-com-table"><table><thead><tr><th>Asunto</th><?php if($admin):?><th>Usuario</th><?php endif;?><th>Estado</th><th>Última actividad</th></tr></thead><tbody><?php foreach(array_slice($threads,0,50) as $t):?><tr><td><a href="<?=$base?>thread=<?=lab_h($t['id'])?>"><?=lab_h($t['subject'])?></a><?=$t['unread']?' · Nuevos mensajes':''?></td><?php if($admin):?><td><?=lab_h($t['username'])?></td><?php endif;?><td><?=$states[$t['status']]??'Nueva'?></td><td><?=scom_date($t['updated_at'])?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$threads):?><p>No hay sugerencias con esos filtros.</p><?php endif;?><?php if(count($threads)>50):?><a class="btn" href="<?=$base?>offset=<?=$offset+50?>&status=<?=lab_h($filter)?>&owner=<?=lab_h($owner)?>">Siguientes</a><?php endif;?></section>
<?php if($selected):?><section class="card" id="conversation" data-com-thread="<?=lab_h($selected['id'])?>" data-com-last="<?=$messages?(int)end($messages)['id']:0?>"><h2><?=lab_h($selected['subject'])?></h2><p>Estado: <?=$states[$selected['status']]?></p><?php if(count($messages)===100):?><a class="btn" href="<?=$base?>thread=<?=lab_h($id)?>&before=<?=(int)$messages[0]['id']?>#conversation">Mensajes anteriores</a><?php endif;?><ol class="sf-com-messages"><?php foreach($messages as $m):?><li><strong><?=lab_h($m['username']??'Cuenta retirada')?><?=($m['role']??'')==='admin'?' · Administración':''?></strong> <time><?=scom_date($m['created_at'])?></time><p class="sf-com-text"><?=lab_h($m['body'])?></p></li><?php endforeach;?></ol>
<?php if($selected['status']!=='closed'):?><form data-com-form><?php scom_hidden('reply',$csrf);?><input type="hidden" name="id" value="<?=lab_h($id)?>"><label>Respuesta<textarea name="body" rows="5" required maxlength="6000"></textarea></label><button class="btn primary" type="submit">Enviar respuesta</button><p data-com-feedback role="status"></p></form><?php endif;?>
<?php if($admin):?><form data-com-form><?php scom_hidden('status',$csrf);?><input type="hidden" name="id" value="<?=lab_h($id)?>"><label>Estado<select name="status"><?php foreach($states as $v=>$label):?><option value="<?=$v?>" <?=$selected['status']===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><button class="btn" type="submit">Actualizar estado</button><p data-com-feedback role="status"></p></form><?php endif;?></section><?php endif;?>
<?php endif;?></main><script src="assets/communication.js?v=save-feedback1" defer></script><script src="assets/navigation.js?v=album-return1"></script></body></html>
